  Definition sregs5 (R' : bvmap 5 word) : Prop :=
    getr R' 8%bv = Z_to_bv 64 parser /\ getr R' 2%bv = Z_to_bv 64 sp /\ getr R' 18%bv = Z_to_bv 64 1
    /\ getr R' 24%bv = Z_to_bv 64 bc /\ getr R' 23%bv = Z_to_bv 64 key.

  Lemma blkA5 : forall R,
    getr R 8%bv = Z_to_bv 64 parser -> getr R 2%bv = Z_to_bv 64 sp -> getr R 18%bv = Z_to_bv 64 1 ->
    exists R', nkeep R R' /\ sregs5 R' /\
      ( (bc = 0 /\ msteps SEGS (st R NSRCH) (st R' NNF_PC))
      \/ (bc <> 0 /\ msteps SEGS (st R NSRCH) (st R' B5_PC)
          /\ getr R' 22%bv = Z_to_bv 64 (hmod key bc) /\ getr R' 11%bv = popcw5 (Z_to_bv 64 bc)) ).
Proof using fx AC L MI rom A M parser sp bl bc key ents U Hkey C56 C64 C72 C80 Hsp0 Hsp1 Hpar.
Ltac finA HR' := eexists; split; [eapply nkeep_of_syms; [exact HR'| reflexivity]|];
