  Lemma blkB5 : forall R idx b q0 (w4 : word),
    getr R 8%bv = Z_to_bv 64 parser -> getr R 2%bv = Z_to_bv 64 sp -> getr R 18%bv = Z_to_bv 64 1 ->
    getr R 24%bv = Z_to_bv 64 bc -> getr R 23%bv = Z_to_bv 64 key ->
    getr R 22%bv = Z_to_bv 64 idx -> getr R 11%bv = w4 ->
    0 <= idx < bc -> bc <> 0 ->
    cell8 SEGS M (bl + 8 * idx) b -> 0 <= b -> b + 8 <= 2 ^ 47 ->
    (b <> 0 -> cell8 SEGS M b q0) -> (b <> 0 -> b mod 8 = 0) ->
    exists R', nkeep R R' /\ sregs5 R' /\ getr R' 22%bv = Z_to_bv 64 idx /\
      ( ((b = 0 \/ q0 = 0) /\ msteps SEGS (st R B5_PC) (st R' NNF_PC))
      \/ (b <> 0 /\ q0 <> 0 /\ 2 <= bv_unsigned w4 /\ msteps SEGS (st R B5_PC) (st R' LM5_PC)
          /\ getr R' 27%bv = Z_to_bv 64 q0 /\ getr R' 10%bv = sxw key)
      \/ (b <> 0 /\ q0 <> 0 /\ bv_unsigned w4 < 2 /\ msteps SEGS (st R B5_PC) (st R' LP5_PC)
          /\ getr R' 27%bv = Z_to_bv 64 q0 /\ getr R' 10%bv = sxw key /\ getr R' 11%bv = Z_to_bv 64 (bc - 1)) ).
Proof using fx AC L MI rom A M parser sp bl bc key ents U Hkey Hpar.
Ltac scB UB1 UB2 UB3 UB4 UB5 Hrd_b := split_scs; try sc_auto1;
      first [ exact UB1 | exact UB2 | exact UB3 | exact UB4 | apply UB5; assumption
            | apply Hrd_b; evs; rewrite ?w_mul, ?w_add by lia; first [reflexivity | f_equal; lia]
            | eapply sc_flat; [evs; rewrite ?w_mul, ?w_add by lia; reflexivity | lia | cbn [a_off]; lia | lia | cbn [a_off]; lia]
            | cbn [sc_denot]; evs; rewrite branch_geu_lit_r by lia; bool_lia
            | idtac ].
Ltac finB HR' := eexists; split; [eapply nkeep_of_syms; [exact HR'| reflexivity]|];
      split; [unfold sregs5; repeat split;
              [ let G := fresh in rreg HR' 8%bv G; exact G | let G := fresh in rreg HR' 2%bv G; exact G
              | let G := fresh in rreg HR' 18%bv G; exact G | let G := fresh in rreg HR' 24%bv G; exact G
              | let G := fresh in rreg HR' 23%bv G; exact G ] |];
