  Definition walk5 (R : bvmap 5 word) (pc0 : Z) (R' : bvmap 5 word) : Prop :=
    nkeep R R' /\ sregs5 R' /\ getr R' 22%bv = getr R 22%bv /\
    ( (exists p v, In (p, (key, v)) ents /\ msteps SEGS (st R pc0) (st R' NFOUND_PC) /\ getr R' 27%bv = Z_to_bv 64 p)
      \/ msteps SEGS (st R pc0) (st R' NNF_PC) ).

  Ltac seed5 R vals :=
    let E := fresh "E" in let HR := fresh "HR" in let HK := fresh "HK" in
    pose (E := Eseed R vals);
    assert (HR : regs_ok E (srs sr_id [(27%bv, EVar 32); (10%bv, EVar 33); (24%bv, EVar 34); (23%bv, EVar 35); (11%bv, EVar 36); (22%bv, EVar 37);
                                        (8%bv, EVar 38); (2%bv, EVar 39); (18%bv, ELit 1)]) R)
      by (apply regs_ok_srs; [apply regs_ok_seed|];
          repeat constructor; cbn [fst snd]; try (intros X; discriminate X); evs; assumption);
    assert (HK : know_ok SEGS E M []) by constructor.

  Ltac alq := lazymatch goal with |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_AND _ (ELit 7)) (ELit 0)) =>
                 eapply sc_trap_align; [evs; reflexivity | lia | apply align16_8; assumption] end.

  Ltac fin_common HR' :=
    split; [eapply nkeep_of_syms; [exact HR'| reflexivity]|];
    split; [unfold sregs5; repeat split;
            [ let G := fresh in rreg HR' 8%bv G; exact G | let G := fresh in rreg HR' 2%bv G; exact G
            | let G := fresh in rreg HR' 18%bv G; exact G | let G := fresh in rreg HR' 24%bv G; exact G
            | let G := fresh in rreg HR' 23%bv G; exact G ] |];
    split; [let G := fresh in rreg HR' 22%bv G; rewrite G; symmetry; assumption|].
  Ltac fin_found5 HR' Hms p v He :=
    lazymatch type of HR' with regs_ok _ _ ?R1 =>
      exists R1; fin_common HR';
      left; exists p, v; split; [rewrite He; apply in_app_iff; right; left; reflexivity|];
      split; [exact Hms | let G := fresh in rreg HR' 27%bv G; exact G]
    end.
  Ltac fin_nf5 HR' Hms :=
    lazymatch type of HR' with regs_ok _ _ ?R1 =>
      exists R1; fin_common HR'; right; exact Hms
    end.

  Lemma loopM5 : forall l2 l1 p k v R,
    ents = l1 ++ (p, (k, v)) :: l2 ->
    getr R 8%bv = Z_to_bv 64 parser -> getr R 2%bv = Z_to_bv 64 sp -> getr R 18%bv = Z_to_bv 64 1 ->
    getr R 27%bv = Z_to_bv 64 p -> getr R 10%bv = sxw key -> getr R 24%bv = Z_to_bv 64 bc ->
    getr R 23%bv = Z_to_bv 64 key -> getr R 22%bv = Z_to_bv 64 (key mod bc) -> bc <> 0 ->
